1	export type Cell = [x: number, y: number];
2	
3	const NEIGHBOR_OFFSETS: ReadonlyArray<Cell> = [
4	  [-1, -1], [-1, 0], [-1, 1],
5	  [ 0, -1],          [ 0, 1],
6	  [ 1, -1], [ 1, 0], [ 1, 1],
7	];
8	
9	const cellKey = ([x, y]: Cell): string => `${x},${y}`;
10	
11	const survives = (isAlive: boolean, neighbors: number): boolean =>
12	  neighbors === 3 || (isAlive && neighbors === 2);
13	
14	const neighborsOf = ([x, y]: Cell): Cell[] =>
15	  NEIGHBOR_OFFSETS.map(([dx, dy]) => [x + dx, y + dy]);
16	
17	export function nextGeneration(cells: Cell[]): Cell[] {
18	  const alive = new Set(cells.map(cellKey));
19	  const candidates = new Map<string, { cell: Cell; neighbors: number }>();
20	
21	  for (const cell of cells) {
22	    for (const neighbor of neighborsOf(cell)) {
23	      const key = cellKey(neighbor);
24	      const entry = candidates.get(key) ?? { cell: neighbor, neighbors: 0 };
25	      entry.neighbors++;
26	      candidates.set(key, entry);
27	    }
28	  }
29	
30	  const result: Cell[] = [];
31	  for (const [key, { cell, neighbors }] of candidates) {
32	    if (survives(alive.has(key), neighbors)) result.push(cell);
33	  }
34	  return result;
35	}
