1	import { describe, it, expect } from "vitest";
2	import { nextGeneration } from "./game-of-life.js";
3	
4	describe("Game of Life - nextGeneration", () => {
5	  it("empty grid stays empty — [] → []", () => {
6	    expect(nextGeneration([])).toEqual([]);
7	  });
8	  it("single live cell dies from underpopulation — [(0,0)] → []", () => {
9	    expect(nextGeneration([[0, 0]])).toEqual([]);
10	  });
11	  it("two adjacent live cells both die from underpopulation — [(0,1),(1,1)] → []", () => {
12	    expect(nextGeneration([[0, 1], [1, 1]])).toEqual([]);
13	  });
14	  it("dead cell with exactly 3 live neighbors becomes alive (reproduction) — [(0,0),(1,0),(0,1)] → includes (1,1)", () => {
15	    const result = nextGeneration([[0, 0], [1, 0], [0, 1]]);
16	    expect(result).toContainEqual([1, 1]);
17	  });
18	  it("live cell with 2 or 3 live neighbors survives (survival) — top center of ###/.../.#. survives", () => {
19	    const result = nextGeneration([[0, 0], [1, 0], [2, 0], [1, 2]]);
20	    expect(result).toContainEqual([1, 0]);
21	  });
22	  it("live cell with more than 3 live neighbors dies from overpopulation — full 3x3 center (1,1) dies", () => {
23	    const cells: [number, number][] = [
24	      [0, 0], [1, 0], [2, 0],
25	      [0, 1], [1, 1], [2, 1],
26	      [0, 2], [1, 2], [2, 2],
27	    ];
28	    const result = nextGeneration(cells);
29	    expect(result).not.toContainEqual([1, 1]);
30	  });
31	  it("block still life remains unchanged — [(0,0),(1,0),(0,1),(1,1)] → same 4 cells", () => {
32	    const block: [number, number][] = [[0, 0], [1, 0], [0, 1], [1, 1]];
33	    const result = nextGeneration(block);
34	    expect(result).toHaveLength(4);
35	    for (const cell of block) {
36	      expect(result).toContainEqual(cell);
37	    }
38	  });
39	  it("blinker oscillates from vertical to horizontal — [(0,0),(0,1),(0,2)] → [(-1,1),(0,1),(1,1)]", () => {
40	    const result = nextGeneration([[0, 0], [0, 1], [0, 2]]);
41	    expect(result).toHaveLength(3);
42	    expect(result).toContainEqual([-1, 1]);
43	    expect(result).toContainEqual([0, 1]);
44	    expect(result).toContainEqual([1, 1]);
45	  });
