export function nextGeneration(cells: Cell[]): Cell[] {
  const alive = new Set(cells.map(cellKey));
  const candidates = new Map<string, { cell: Cell; neighbors: number }>();

  for (const cell of cells) {
    for (const neighbor of neighborsOf(cell)) {
      const key = cellKey(neighbor);
      const entry = candidates.get(key) ?? { cell: neighbor, neighbors: 0 };
      candidates.set(key, { cell: entry.cell, neighbors: entry.neighbors + 1 });
    }
  }

  return Array.from(candidates)
    .filter(([key, { neighbors }]) => survives(alive.has(key), neighbors))
    .map(([, { cell }]) => cell);
}

